//! # `enumx`: experiments E1 and E2, the enumeration side of the probe
//!
//! The X1 bar is enumeration (VOS01 section 5.6): every state and argument of a claim is run
//! through the implementation and the model.  The solver rows of the probe are about X3; these
//! two are about whether X1's budget is the right size.
//!
//! ## E1: throughput of the generated by-value harness
//!
//! The harness is *generated* from a Warrant document by `coding_adventures_warrant_grammar`'s
//! evidence generator.  Two committed, generated harnesses are `include!`d here, the way each
//! package's own test shim includes its own, and the harness's public `exh_<claim>(Fault)`
//! entry points are driven in process:
//!
//! ```text
//!   vos-sched-fp-bitmap   the real VOS-011 scheduler at N = 8     products 256 and 65,536
//!   vos-probe-ready       the narrowed fixture                    65,536 (both forms),
//!                                                                 262,144 (N = 10) and 393,216
//! ```
//!
//! A row times one call: cases, wall milliseconds, cases per second.  The control (G3) calls
//! the same claim against a deliberately broken adapter (`Fault`), which the harness must
//! report as failing.  The `N = 11` knob is the refusal: the generator's own domain
//! accounting (`domain::resolve_binders`, the function the evidence generator calls) must
//! refuse `insert` at eleven `Bool`s and a `U8` index (524,288 cases) with `W0706`, and
//! accept the same document at ten.
//!
//! ## E2: where the domain bounds bite
//!
//! A claim with `k` binders of `Bytes<W>` has (one binder's domain size)^k cases (a binder holds
//! `4 + 3W` values, except `Bytes<1>`, which holds all 256) and the sum of the binders' domain
//! bytes.  The generator refuses a claim over 400,000 cases or 64 MiB of domain (`W0706`) and a
//! width over 4096 (`W0707`).  A row resolves the binders with the generator's
//! own function, and for an accepted claim materialises every binder's domain and counts the
//! product, so the child's peak resident memory is the measured cost of holding it.

use crate::exp::RowSpec;
use crate::inst::sha_hex;
use crate::row::{Control, Row};
use coding_adventures_warrant_grammar::domain::{resolve_binders, DomainEnv};
use coding_adventures_warrant_grammar::layout::{capture_layout, LayoutLimits};
use coding_adventures_warrant_grammar::parser::{parse_document, Declaration, ParserLimits};
use coding_adventures_warrant_grammar::source::{SourceDocument, SourceLimits};
use std::time::Instant;

/// The real scheduler's committed generated harness, included in its own module.
///
/// It installs the harness's WX-H allocation observer as the process's global allocator (a
/// generated `unsafe impl GlobalAlloc`).  The observer is inert outside an observed call: one
/// thread-local check per allocation, which changes no conflict or work count.
#[allow(
    dead_code,
    unused_variables,
    unused_parens,
    unused_imports,
    unsafe_code,
    clippy::all
)]
mod real {
    include!("../../../../packages/rust/vos-sched-fp-bitmap/tests/generated/warrant_evidence.rs");
}

/// The fixture's committed generated harness.
#[allow(
    dead_code,
    unused_variables,
    unused_parens,
    unused_imports,
    clippy::all
)]
mod fixture {
    include!("../../../../packages/rust/vos-probe-ready/tests/generated/warrant_evidence.rs");
}

/// The Warrant documents the harnesses are generated from.  An E1 row's instance digest is the
/// digest of the *document*, not of the generated text: regenerating a harness with a newer
/// generator (which another stream does) must not break a probe whose claim set is unchanged,
/// while a changed claim changes the document, the case counts and so the row.
const REAL_DOC: &[u8] = include_bytes!("../../../../specs/vos-sched-fp-bitmap.warrant");
const FIXTURE_DOC: &[u8] = include_bytes!("../../../../specs/vos-probe-ready.warrant");

/// The E1 knobs: `(claim, fixture, binder product, in the quick tier)`.
pub const E1_KNOBS: &[(&str, &str, i64, bool)] = &[
    ("dispatch_policy", "vos-sched-fp-bitmap", 256, true),
    ("insert_safe", "vos-sched-fp-bitmap", 65_536, false),
    ("insert_n8_bool", "vos-probe-ready", 65_536, false),
    ("insert_n8_mask", "vos-probe-ready", 65_536, false),
    ("insert_n10", "vos-probe-ready", 262_144, false),
    ("insert_n8_mask_tagged", "vos-probe-ready", 393_216, false),
    ("insert_n11", "refusal", 524_288, true),
];

/// What one call of a generated claim returned.
struct Ran {
    passed: bool,
    cases: u64,
    discarded: u64,
    ms: f64,
}

/// Run claim `claim` of `fixture` with the real adapter (`fault = false`) or the broken one.
fn run_claim(fixture: &str, claim: &str, fault: bool) -> Result<Ran, String> {
    let t0 = Instant::now();
    macro_rules! go {
        ($m:ident, $f:ident, $bad:ident) => {{
            let fl = if fault {
                $m::Fault::$bad
            } else {
                $m::Fault::None
            };
            let (v, s) = $m::$f(fl);
            (
                matches!(v, coding_adventures_test_bootstrap::Verdict::Pass),
                s.cases,
                s.discarded,
            )
        }};
    }
    let (passed, cases, discarded) = match (fixture, claim) {
        ("vos-sched-fp-bitmap", "dispatch_policy") => go!(real, exh_dispatch_policy, WrongCtor),
        ("vos-sched-fp-bitmap", "insert_safe") => go!(real, exh_insert_safe, WrongCtor),
        ("vos-probe-ready", "insert_n8_bool") => go!(fixture, exh_insert_n8_bool, ShiftMask),
        ("vos-probe-ready", "insert_n8_mask") => go!(fixture, exh_insert_n8_mask, ShiftMask),
        ("vos-probe-ready", "insert_n10") => go!(fixture, exh_insert_n10, ShiftMask),
        ("vos-probe-ready", "insert_n8_mask_tagged") => {
            go!(fixture, exh_insert_n8_mask_tagged, ShiftMask)
        }
        ("vos-probe-ready", "pick_n8") => go!(fixture, exh_pick_n8, ShiftMask),
        _ => return Err(format!("no claim {claim} in {fixture}")),
    };
    Ok(Ran {
        passed,
        cases,
        discarded,
        ms: t0.elapsed().as_secs_f64() * 1000.0,
    })
}

/// An E1 row.
pub fn e1_row(spec: &RowSpec) -> Row {
    let mut row = Row::new("E1", spec.knob.clone(), "enum", spec.seed, spec.seeds);
    row.cap = "none".into();
    let claim = spec.knob.s("claim").to_string();
    let fixture = spec.knob.s("fixture").to_string();
    if fixture == "refusal" {
        return e1_refusal(row, spec.knob.int("binders"));
    }
    let bytes = if fixture == "vos-sched-fp-bitmap" {
        REAL_DOC
    } else {
        FIXTURE_DOC
    };
    row.instance_sha256 = sha_hex(bytes);
    row.control_instance_sha256 = row.instance_sha256.clone();
    let ran = match run_claim(&fixture, &claim, false) {
        Ok(r) => r,
        Err(e) => {
            row.result = "crashed".into();
            row.note = e;
            return row;
        }
    };
    row.result = if ran.passed {
        "pass".into()
    } else {
        "fail".into()
    };
    row.solve_ms = ran.ms;
    row.worst_step_solve_ms = ran.ms;
    row.metrics = vec![
        ("cases".into(), ran.cases as f64),
        ("discarded".into(), ran.discarded as f64),
        ("run_ms".into(), ran.ms),
        (
            "cases_per_s".into(),
            if ran.ms > 0.0 {
                ran.cases as f64 / (ran.ms / 1000.0)
            } else {
                0.0
            },
        ),
        ("binder_product".into(), spec.knob.int("binders") as f64),
    ];
    row.note = "run-only: the harness is compiled into the probe, so its compile time is the probe's build".into();
    // G3: the same claim against a broken adapter must fail.
    row.control = match run_claim(&fixture, &claim, true) {
        Ok(c) if !c.passed => Control {
            result: "caught".into(),
            model_checks_cnf: true,
            replayed: true,
        },
        Ok(_) => Control::none("the broken adapter passed"),
        Err(e) => Control::none(&e),
    };
    row
}

/// The warrant document `op f(b0: Bool, ..., b<n-1>: Bool, t: U8) -> U8`.
fn insert_doc(n: usize) -> String {
    let params: Vec<String> = (0..n)
        .map(|i| format!("b{i}: Bool"))
        .chain(std::iter::once("t: U8".to_string()))
        .collect();
    format!(
        "warrant probe_insert v1\n  op f({}) -> U8\n",
        params.join(", ")
    )
}

/// The warrant document `op f(x1: Bytes<W>, ...) -> U8` with `k` binders.
fn bytes_doc(w: usize, k: usize) -> String {
    let params: Vec<String> = (1..=k).map(|i| format!("x{i}: Bytes<{w}>")).collect();
    format!(
        "warrant probe_bytes v1\n  op f({}) -> U8\n",
        params.join(", ")
    )
}

/// What the generator's accounting says about the binders of the first `op` of `src`.
struct Accounting {
    accepted: bool,
    code: String,
    product: u64,
    bytes: u64,
    /// For an accepted claim: the domains were materialised and the product counted.
    enumerated: u64,
    held: u64,
}

fn account(src: &str, enumerate: bool) -> Result<Accounting, String> {
    let doc = SourceDocument::admit(src.as_bytes(), SourceLimits::default())
        .map_err(|e| format!("{e:?}"))?;
    let layout = capture_layout(&doc, LayoutLimits::default()).map_err(|e| format!("{e:?}"))?;
    let file =
        parse_document(&layout, &doc, ParserLimits::default()).map_err(|e| format!("{e:?}"))?;
    let env = DomainEnv::new(&file);
    let Some(Declaration::Op(op)) = file
        .declarations
        .iter()
        .find(|d| matches!(d, Declaration::Op(_)))
    else {
        return Err("the document has no op".into());
    };
    match resolve_binders(&env, &op.params, None, 400_000, "f", op.span) {
        Ok(r) => {
            let (mut enumerated, mut held) = (0u64, 0u64);
            if enumerate {
                // The generated harness materialises every binder's domain before it loops; do
                // the same and keep them alive while the product is counted.
                let all: Vec<Vec<_>> = r.domains.iter().map(|d| d.iter().collect()).collect();
                held = all.iter().map(|v| v.len() as u64).sum();
                if let Some(it) = r.iter_from(0) {
                    enumerated = it.count() as u64;
                }
                drop(all);
            }
            Ok(Accounting {
                accepted: true,
                code: String::new(),
                product: r.product,
                bytes: r.bytes,
                enumerated,
                held,
            })
        }
        Err(e) => {
            // The refused claim's own numbers, from the generator's accounting of each binder.
            let mut product = 1u64;
            let mut bytes = 0u64;
            for p in &op.params {
                if let Ok(d) = env.domain_of_type(&p.param_type, p.span) {
                    product = product.saturating_mul(d.domain_size().unwrap_or(u64::MAX));
                    bytes = bytes.saturating_add(d.domain_bytes().unwrap_or(u64::MAX));
                }
            }
            Ok(Accounting {
                accepted: false,
                code: e.code.to_string(),
                product,
                bytes,
                enumerated: 0,
                held: 0,
            })
        }
    }
}

fn e1_refusal(mut row: Row, binders: i64) -> Row {
    let n11 = account(&insert_doc(11), false);
    let n10 = account(&insert_doc(10), false);
    row.instance_sha256 = sha_hex(insert_doc(11).as_bytes());
    row.control_instance_sha256 = sha_hex(insert_doc(10).as_bytes());
    match (n11, n10) {
        (Ok(a), Ok(b)) => {
            row.metrics = vec![
                ("binder_product".into(), a.product as f64),
                ("control_binder_product".into(), b.product as f64),
                ("expected_product".into(), binders as f64),
            ];
            if !a.accepted && a.code == "W0706" && a.product as i64 == binders {
                row.result = "refused".into();
                row.note = format!(
                    "W0706: insert at N = 11 is {} cases, over the 400000 budget",
                    a.product
                );
            } else {
                row.result = "crashed".into();
                row.note = format!(
                    "N = 11 was not refused with W0706 (accepted: {}, code {:?})",
                    a.accepted, a.code
                );
            }
            // The control: the same document at N = 10 is accepted, so the refusal is the budget.
            row.control = if b.accepted && b.product == 262_144 {
                Control {
                    result: "caught".into(),
                    model_checks_cnf: true,
                    replayed: true,
                }
            } else {
                Control::none("the N = 10 control was refused")
            };
        }
        (Err(e), _) | (_, Err(e)) => {
            row.result = "crashed".into();
            row.note = e;
        }
    }
    row
}

/// An E2 row: resolve the binders of `k` `Bytes<W>` binders with the generator's accounting.
pub fn e2_row(spec: &RowSpec) -> Row {
    let mut row = Row::new("E2", spec.knob.clone(), "enum", spec.seed, spec.seeds);
    let (w, k) = (
        spec.knob.int("width") as usize,
        spec.knob.int("binders") as usize,
    );
    let src = bytes_doc(w, k);
    row.instance_sha256 = sha_hex(src.as_bytes());
    let t0 = Instant::now();
    let acc = match account(&src, true) {
        Ok(a) => a,
        Err(e) => {
            row.result = "crashed".into();
            row.note = e;
            return row;
        }
    };
    let ms = t0.elapsed().as_secs_f64() * 1000.0;
    row.solve_ms = ms;
    row.worst_step_solve_ms = ms;
    // The expectation is the generator's OWN per-binder accounting against its two budgets:
    // the case count over 400,000 or the domain bytes over 64 MiB.  (An earlier draft used the
    // closed form `(4 + 3W)^k`, which is wrong at W = 1: a one-byte binder enumerates all 256
    // values.)  What this row checks is that the generator's refuse-or-accept decision is the
    // decision those two numbers give.
    let over_cases = acc.product > 400_000;
    let over_bytes = acc.bytes > 64 * 1024 * 1024;
    row.metrics = vec![
        ("binder_product".into(), acc.product as f64),
        ("domain_bytes".into(), acc.bytes as f64),
        ("enumerated".into(), acc.enumerated as f64),
        ("values_held".into(), acc.held as f64),
        ("over_cases".into(), over_cases as u8 as f64),
        ("over_bytes".into(), over_bytes as u8 as f64),
        ("run_ms".into(), ms),
    ];
    let agrees = acc.accepted == !(over_cases || over_bytes);
    if !agrees {
        row.result = "crashed".into();
        row.note = format!(
            "the generator's decision (accepted {}) disagrees with its own numbers ({} cases, {} bytes)",
            acc.accepted, acc.product, acc.bytes
        );
    } else if acc.accepted {
        row.result = "pass".into();
        row.note = format!(
            "accepted: {} cases, {} domain bytes",
            acc.product, acc.bytes
        );
    } else {
        row.result = "refused".into();
        row.note = format!(
            "{}: {} cases, {} domain bytes ({})",
            acc.code,
            acc.product,
            acc.bytes,
            if over_cases {
                "over the case budget"
            } else {
                "over the byte budget"
            }
        );
    }
    // G3: a binder wider than the cap must be refused (W0707).
    row.control = match account(&bytes_doc(4097, 1), false) {
        Ok(c) if !c.accepted && c.code == "W0707" => Control {
            result: "caught".into(),
            model_checks_cnf: true,
            replayed: true,
        },
        Ok(c) => Control::none(&format!(
            "width 4097 was not refused with W0707 (code {:?})",
            c.code
        )),
        // The width is refused already while the document is read: also a refusal.
        Err(_) => Control {
            result: "caught".into(),
            model_checks_cnf: true,
            replayed: true,
        },
    };
    row.control_instance_sha256 = sha_hex(bytes_doc(4097, 1).as_bytes());
    row
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::row::{Knob, Kv};

    fn spec(exp: &str, knob: Knob) -> RowSpec {
        RowSpec {
            experiment: exp.into(),
            knob,
            mode: "enum".into(),
            seed: 1,
            seeds: 5,
            tier: "quick".into(),
        }
    }

    #[test]
    fn the_real_scheduler_harness_runs_and_its_control_is_caught() {
        let knob = Knob::of(&[
            ("claim", Kv::S("dispatch_policy".into())),
            ("fixture", Kv::S("vos-sched-fp-bitmap".into())),
            ("binders", Kv::I(256)),
        ]);
        let r = e1_row(&spec("E1", knob));
        assert_eq!(r.result, "pass", "{}", r.note);
        assert_eq!(r.metric("cases"), Some(256.0));
        assert!(r.control.ok(), "{:?}", r.control);
    }

    #[test]
    fn every_fixture_claim_runs_with_the_published_binder_product() {
        for (claim, fixture, binders, _) in E1_KNOBS {
            if *fixture == "refusal" {
                continue;
            }
            let knob = Knob::of(&[
                ("claim", Kv::S(claim.to_string())),
                ("fixture", Kv::S(fixture.to_string())),
                ("binders", Kv::I(*binders)),
            ]);
            let r = e1_row(&spec("E1", knob));
            assert_eq!(r.result, "pass", "{claim}: {}", r.note);
            assert!(r.control.ok(), "{claim}: {:?}", r.control);
            assert_eq!(
                r.metric("cases").unwrap() as i64 + r.metric("discarded").unwrap() as i64,
                *binders,
                "{claim}"
            );
        }
    }

    #[test]
    fn an_unknown_claim_is_reported_not_run() {
        let knob = Knob::of(&[
            ("claim", Kv::S("nope".into())),
            ("fixture", Kv::S("vos-probe-ready".into())),
            ("binders", Kv::I(1)),
        ]);
        let r = e1_row(&spec("E1", knob));
        assert_eq!(r.result, "crashed");
        assert!(r.note.contains("no claim"));
    }

    #[test]
    fn n_eleven_is_refused_with_w0706_and_n_ten_is_the_control() {
        let knob = Knob::of(&[
            ("claim", Kv::S("insert_n11".into())),
            ("fixture", Kv::S("refusal".into())),
            ("binders", Kv::I(524_288)),
        ]);
        let r = e1_row(&spec("E1", knob));
        assert_eq!(r.result, "refused", "{}", r.note);
        assert!(r.note.contains("W0706"));
        assert!(r.control.ok());
        assert_eq!(r.metric("control_binder_product"), Some(262_144.0));
        // A mismatched expectation is not silently accepted.
        let knob = Knob::of(&[
            ("claim", Kv::S("insert_n11".into())),
            ("fixture", Kv::S("refusal".into())),
            ("binders", Kv::I(1)),
        ]);
        assert_eq!(e1_row(&spec("E1", knob)).result, "crashed");
    }

    #[test]
    fn e2_one_byte_binders_enumerate_all_256_values() {
        // The closed form 4 + 3W would say 7 values; the generator's domain for Bytes<1> is 256.
        let two = e2_row(&spec(
            "E2",
            Knob::of(&[("width", Kv::I(1)), ("binders", Kv::I(2))]),
        ));
        assert_eq!(
            (two.result.as_str(), two.metric("binder_product")),
            ("pass", Some(65_536.0)),
            "{}",
            two.note
        );
        let three = e2_row(&spec(
            "E2",
            Knob::of(&[("width", Kv::I(1)), ("binders", Kv::I(3))]),
        ));
        assert_eq!(three.result, "refused", "{}", three.note);
        assert_eq!(three.metric("binder_product"), Some(16_777_216.0));
    }

    #[test]
    fn e2_accepts_what_fits_and_refuses_what_does_not() {
        let fits = e2_row(&spec(
            "E2",
            Knob::of(&[("width", Kv::I(8)), ("binders", Kv::I(2))]),
        ));
        assert_eq!(fits.result, "pass", "{}", fits.note);
        assert_eq!(fits.metric("binder_product"), Some(784.0));
        assert_eq!(fits.metric("enumerated"), Some(784.0));
        assert!(fits.control.ok());
        let over = e2_row(&spec(
            "E2",
            Knob::of(&[("width", Kv::I(256)), ("binders", Kv::I(2))]),
        ));
        assert_eq!(over.result, "refused");
        assert!(
            over.note.contains("W0706") && over.note.contains("case budget"),
            "{}",
            over.note
        );
        let wide = e2_row(&spec(
            "E2",
            Knob::of(&[("width", Kv::I(4096)), ("binders", Kv::I(1))]),
        ));
        assert_eq!(wide.result, "pass", "{}", wide.note);
        assert!(wide.metric("domain_bytes").unwrap() < 64.0 * 1024.0 * 1024.0);
    }

    #[test]
    fn a_document_that_does_not_parse_is_an_error_not_a_panic() {
        assert!(account("not a warrant document", false).is_err());
        assert!(account("warrant t v1\n  model m() -> U8 = 1u8\n", false).is_err());
    }
}
